1	// 首页“创建公开房间”在创建结果返回前继续修改表单的界面回归测试。
2	//
3	// 与其他浏览器回归文件的分工：
4	//   - ui.test.mjs：创建成功/被拒的基本路径、成功后列表竞态刷新、名称整理；
5	//   - ui-capacity-linkage.test.mjs：规则与人数联动本身；
6	//   - ui-create-connection-failure.test.mjs：创建请求未送达服务的连接失败；
7	//   - 本文件只盯住“点击创建房间之后、创建结果返回之前继续编辑表单”这一段：
8	//     四项（名称、游戏规则、人数上限、每步时间限制）等待期间仍可编辑，但本次
9	//     创建固定使用点击提交时的配置快照；等待期间的输入属于下一次尚未提交的
10	//     填写，不能混进已发出的请求，也不能自动创建成另一个房间。
11	//
12	// 覆盖的产品行为：
13	//   1. 成功创建时，提示编号与列表新房间对应“提交时”的配置（名称按现有规则
14	//      去掉首尾空白）；是否复位表单以“创建结果返回时”的实际填写值为准——
15	//      四项与提交时逐项完全一致才恢复初始状态（等待期间改过又全部恢复原样
16	//      仍复位），任一项不同就整体保留当前四项（包括未修改的项与已经清空的
17	//      项），不能只留变化字段、不能把其他项回退旧值，未填完整不自动补齐；
18	//      仅调整名称首尾空白、即使整理后保存名称相同，也算输入变化、整体保留；
19	//   2. 保留下来的规则与人数选择状态必须相符（五子棋固定 2 人、飞行棋 2 至 4
20	//      人的联动等待期间照常生效），保留后继续按现有规则接受页面校验；
21	//   3. 成功且保留时提示同时说明“本次已创建成功、当前填写尚未提交”，用户可
22	//      直接继续编辑或再次提交，只有再次提交才使用当前配置创建下一间房；
23	//   4. 创建被服务拒绝时显示服务给出的原因、不出现成功编号、已有列表保持
24	//      原样，等待期间的最新四项仍保留，不因失败回退到提交时的内容；
25	//   5. 提交等待及随后列表刷新完成前创建按钮保持不可用，重复点击/再次提交
26	//      不会增加第二个房间；本次处理完成后按钮恢复可用。
27	//
28	// 运行：npm test（需要系统 Chrome，可用 CHROME_PATH 指定路径）。
29	
30	import { test, before, after } from 'node:test';
31	import assert from 'node:assert/strict';
32	import { execFile, spawn } from 'node:child_process';
33	import { mkdtemp, writeFile, rm } from 'node:fs/promises';
34	import { tmpdir } from 'node:os';
35	import path from 'node:path';
36	import { promisify } from 'node:util';
37	import puppeteer from 'puppeteer-core';
38	
39	const repoRoot = import.meta.dirname;
40	const chromePath = process.env.CHROME_PATH || '/usr/bin/google-chrome';
41	
42	const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
43	
44	let serverBin;
45	let browser;
46	
47	// 与其他界面回归文件相同的种子记录：创建前后用来比对列表内容与次序不变。
48	const SEED_ALPHA =
49	  '{"id":"seed-alpha","name":"晨间飞行棋","game":"ludo","capacity":4,"turnSeconds":30,' +
50	  '"status":"playing","visibility":"public","createdAt":"2026-01-01T08:00:00Z","note":"保留我","tags":["老友","周赛"]}';
51	const SEED_BETA =
52	  '{"id":"seed-beta","name":"午夜五子棋","game":"gomoku","capacity":2,"turnSeconds":0,' +
53	  '"status":"waiting","visibility":"public","createdAt":"2026-01-02T23:00:00Z","extra":{"rank":3}}';
54	
55	const SUCCESS_PREFIX = '房间已创建，编号：';
56	// 成功且表单保留时，成功编号之后追加的说明文案（须与 index.html 完全一致，
57	// 含全角引号与句号）。
58	const RETAIN_SUFFIX =
59	  '。表单中当前填写的内容尚未提交，不会自动创建房间；如需创建下一间，可直接点击“创建房间”。';
60	const NAME_REQUIRED_TEXT = '房间名称不能为空。';
61	const CAPACITY_REQUIRED_TEXT = '请选择人数上限。';
62	
63	// 创建成功且表单复位后的初始状态：名称/时间为空、规则未选、人数不可填写。
64	const RESET_FORM = {
65	  name: '',
66	  game: '',
67	  capacity: '',
68	  capacityDisabled: true,
69	  turnSeconds: '',
70	  submitDisabled: false,
71	};
72	
73	before(async () => {
74	  const dir = await mkdtemp(path.join(tmpdir(), 'score-arena-uibin-'));
75	  serverBin = path.join(dir, 'score-arena');
76	  await promisify(execFile)('go', ['build', '-o', serverBin, '.'], { cwd: repoRoot });
77	  browser = await puppeteer.launch({
78	    executablePath: chromePath,
79	    headless: true,
80	    args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
81	  });
82	});
83	
84	after(async () => {
85	  if (browser) await browser.close();
86	  if (serverBin) await rm(path.dirname(serverBin), { recursive: true, force: true });
87	});
88	
89	// startServer 在 dataDir 上启动真实服务子进程（--port 0 自动选端口），返回基地址。
90	function startServer(t, dataDir) {
91	  const proc = spawn(
92	    serverBin,
93	    ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
94	    { stdio: ['ignore', 'pipe', 'inherit'] },
95	  );
96	  t.after(() => { proc.kill('SIGKILL'); });
97	  return new Promise((resolve, reject) => {
98	    let buf = '';
99	    const timer = setTimeout(() => reject(new Error('等待服务监听地址超时')), 15000);
100	    proc.stdout.on('data', (chunk) => {
101	      buf += chunk.toString();
102	      const m = buf.match(/listening on (http:\/\/\S+)/);
103	      if (m) {
104	        clearTimeout(timer);
105	        resolve(m[1]);
106	      }
107	    });
108	    proc.on('exit', (code) => {
109	      clearTimeout(timer);
110	      reject(new Error(`服务在输出监听地址前退出，退出码 ${code}`));
111	    });
112	  });
113	}
114	
115	async function seedRooms(dataDir, ...records) {
116	  await writeFile(path.join(dataDir, 'rooms.json'), '[\n' + records.join(',\n') + '\n]\n');
117	}
118	
119	// 每个用例使用独立的数据目录、服务进程与页面；打开页面时已有两条种子房间。
120	async function setupPage(t) {
121	  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-uidata-'));
122	  t.after(() => rm(dataDir, { recursive: true, force: true }));
123	  await seedRooms(dataDir, SEED_ALPHA, SEED_BETA);
124	  const baseURL = await startServer(t, dataDir);
125	  const page = await browser.newPage();
