208	function nextPostResponse(page) {
209	  return new Promise((resolve, reject) => {
210	    page.on('response', (resp) => {
211	      if (resp.request().method() === 'POST' && resp.url().endsWith('/api/rooms')) {
212	        resp.json().then(
213	          (body) => resolve({ status: resp.status(), body }),
214	          reject,
215	        );
216	      }
217	    });
218	  });
219	}
