  assert.deepEqual(rows.slice(0, 2), initialRows, '原有房间的内容或次序被改变');
  assert.equal(rows[2].cells[0], created.body.id, '列表新房间编号应与提示一致');
  assert.equal(rows[2].cells[1], '提交时的五子棋房间');
